package io.spring.core.article;

import static java.util.stream.Collectors.toList;
import io.spring.Util;
import java.util.HashSet;
import java.util.List;
import java.util.UUID;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.NoArgsConstructor;
import org.joda.time.DateTime;

@Getter
@NoArgsConstructor
@EqualsAndHashCode(of = { "id" })
public class Article {

    private String userId;

    private String id;

    private String slug;

    private String title;

    private String description;

    private String body;

    private List<Tag> tags;

    private DateTime createdAt;

    private DateTime updatedAt;

    public Article(String title, String description, String body, List<String> tagList, String userId) {
        this(title, description, body, tagList, userId, new DateTime());
    }

    public Article(String title, String description, String body, List<String> tagList, String userId, DateTime createdAt) {
        this.id = UUID.randomUUID().toString();
        this.slug = toSlug(title);
        this.title = title;
        this.description = description;
        this.body = body;
        this.tags = new HashSet<>(tagList).stream().map(Tag::new).collect(toList());
        this.userId = userId;
        this.createdAt = createdAt;
        this.updatedAt = createdAt;
    }

    public void update(String title, String description, String body) {
        if (!Util.isEmpty(title)) {
            this.title = title;
            this.slug = toSlug(title);
            this.updatedAt = new DateTime();
        }
        if (!Util.isEmpty(description)) {
            this.description = description;
            this.updatedAt = new DateTime();
        }
        if (!Util.isEmpty(body)) {
            this.body = body;
            this.updatedAt = new DateTime();
        }
    }

    public static String toSlug(String title) {
        return title.toLowerCase().replaceAll("[\\&|[\\uFE30-\\uFFA0]|\\’|\\”|\\s\\?\\,\\.]+", "-");
    }
}

package io.spring.core.article;

import java.util.Optional;

public interface ArticleRepository {

    void save(Article article);

    Optional<Article> findById(String id);

    Optional<Article> findBySlug(String slug);

    void remove(Article article);
}

package io.spring.core.user;

import io.spring.Util;
import java.util.UUID;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Getter
@NoArgsConstructor
@EqualsAndHashCode(of = { "id" })
public class User {

    private String id;

    private String email;

    private String username;

    private String password;

    private String bio;

    private String image;

    public User(String email, String username, String password, String bio, String image) {
        this.id = UUID.randomUUID().toString();
        this.email = email;
        this.username = username;
        this.password = password;
        this.bio = bio;
        this.image = image;
    }

    public void update(String email, String username, String password, String bio, String image) {
        if (!Util.isEmpty(email)) {
            this.email = email;
        }
        if (!Util.isEmpty(username)) {
            this.username = username;
        }
        if (!Util.isEmpty(password)) {
            this.password = password;
        }
        if (!Util.isEmpty(bio)) {
            this.bio = bio;
        }
        if (!Util.isEmpty(image)) {
            this.image = image;
        }
    }
}

package io.spring;

public class Util {

    public static boolean isEmpty(String value) {
        return value == null || value.isEmpty();
    }
}

package io.spring.core.article;

import java.util.UUID;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.NoArgsConstructor;

@NoArgsConstructor
