package io.spring.application.article;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import io.spring.core.article.Article;
import io.spring.core.article.ArticleRepository;
import io.spring.core.article.Tag;
import io.spring.core.user.User;
import java.util.Arrays;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class ArticleCommandServiceTest {

    @Mock
    private ArticleRepository articleRepository;

    @InjectMocks
    private ArticleCommandService articleCommandService;

    // GreyTest trace: createArticle | article creation and save | BR-022, BR-023, BR-024 -> TP-039 -> TC-130
    @Test
    void createArticle_CreatesSavesAndReturnsArticle() {
        // Arrange
        User creator = org.mockito.Mockito.mock(User.class);
        when(creator.getId()).thenReturn("user-1");
        NewArticleParam param = new NewArticleParam(
                "Hello World", "A description", "Article body", Arrays.asList("java", "spring"));
        ArgumentCaptor<Article> savedArticleCaptor = ArgumentCaptor.forClass(Article.class);

        // Act
        Article result = articleCommandService.createArticle(param, creator);

        // Assert
        verify(articleRepository).save(any(Article.class));
        Article savedArticle = savedArticleCaptor.getValue();
        assertSame(savedArticle, result);
        assertEquals("Hello World", result.getTitle());
        assertEquals("A description", result.getDescription());
        assertEquals("Article body", result.getBody());
        assertEquals("user-1", result.getUserId());
        assertNotNull(result.getId());

        List<Tag> tags = result.getTags();
        assertEquals(2, tags.size());
        assertEquals(2, tags.stream().map(Tag::getName).distinct().count());
        assertEquals(java.util.Set.of("java", "spring"),
                tags.stream().map(Tag::getName).collect(java.util.stream.Collectors.toSet()));
    }
}
